import{_ as t,H as a,f as l,i as r}from"./chunks/framework.BH2BK_3i.js";const p=JSON.parse('{"title":"复习课（三）| Bigtable","description":"","frontmatter":{},"headers":[{"level":2,"title":"Bigtable介绍","slug":"bigtable介绍","link":"#bigtable介绍","children":[]},{"level":2,"title":"可运维性强","slug":"可运维性强","link":"#可运维性强","children":[]},{"level":2,"title":"数据模型","slug":"数据模型","link":"#数据模型","children":[]},{"level":2,"title":"架构与实现","slug":"架构与实现","link":"#架构与实现","children":[]},{"level":2,"title":"每秒百万级别的随机读写","slug":"每秒百万级别的随机读写","link":"#每秒百万级别的随机读写","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"大数据经典论文解读/复习课（三）-Bigtable.md","filePath":"大数据经典论文解读/复习课（三）-Bigtable.md","lastUpdated":1779819465000}'),i={name:"大数据经典论文解读/复习课（三）-Bigtable.md"};function b(n,e,s,o,g,B){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="复习课-三-bigtable" tabindex="-1">复习课（三）| Bigtable <a class="header-anchor" href="#复习课-三-bigtable" aria-label="Permalink to &quot;复习课（三）| Bigtable&quot;">​</a></h1><p>你好，我是黄金。欢迎来到第三期复习课，今天我们来回顾复习下Bigtable这篇论文的知识点。</p><h2 id="bigtable介绍" tabindex="-1"><strong>Bigtable介绍</strong> <a class="header-anchor" href="#bigtable介绍" aria-label="Permalink to &quot;**Bigtable介绍**&quot;">​</a></h2><p>在Bigtable论文中提到，当年Google的很多产品都使用Bigtable存储数据，包括Web索引、谷歌地球、谷歌金融。不管是完成批处理，还是实时数据服务，Bigtable表现得都很好。也就是说， <strong>Bigtable不仅擅长顺序读写，也擅长随机读写</strong>。</p><h2 id="可运维性强" tabindex="-1"><strong>可运维性强</strong> <a class="header-anchor" href="#可运维性强" aria-label="Permalink to &quot;**可运维性强**&quot;">​</a></h2><p>徐老师在 <a href="https://time.geekbang.org/column/article/423600" target="_blank" rel="noreferrer">08讲</a> 中，先是讲了为什么MySQL集群难以支撑百万级别的随机读写IOPS，主要的原因是 <strong>可运维性差</strong>。第一，数据分区不灵活，导致随着数据规模的增长，有些分区数据多，有些分区数据少；第二，服务器扩容不灵活，扩容时要么需要移动大量数据，要么需要成倍增加服务器；第三，故障恢复时只能自动恢复主节点，不能自动恢复备份节点。</p><p><strong>那么，Bigtable是如何解决这些运维问题的呢？</strong></p><p>首先，为了应对数据规模的增长，我们需要把数据分配到不同的服务器，这个行为叫做 <strong>分区</strong>。Bigtable的分区方式是为每个分区分配一段连续的 <strong>行键</strong>（Row Key），每个分区管理固定大小的数据。当分区数据超过阈值时，比如128MB，分区就会自动分裂。之所以这样做，是因为数据分布可能是不均匀的，动态分区可以让数据在服务器上分布更均匀。</p><p>然后，正是由于每个分区负责的行键区间不固定，就需要一个 <strong>组件</strong> 帮助客户端在发起请求时，找到行键所在的数据分区。这个组件需要让集群中的所有节点达成共识，确定哪个区间的数据在哪个分区上，由哪台服务器提供服务。它的名字就是 <strong>Chubby</strong>，在后续的论文解读课上我们还会深入学习，目前只需要知道它是 <strong>用来在集群中对某件事达成共识</strong>。</p><p>另外，Bigtable中还分离了存储模块和在线服务，采用不同的方法应对扩容和故障恢复。Bigtable的分区数据叫做Tablet，存储在GFS上，很自然地具备了扩容和容灾的特性。而负责处理读写请求的在线服务是Tablet Server，Tablet Server支持动态增加和删除，Bigtable会把Tablet合理地分配给存活的Tablet Server。</p><p>我们应该也知道， <strong>MySQL的容灾方式是为主服务指定一个备份服务</strong>，主服务挂了就切到备份服务上，但是如果这个备份服务也挂了就麻烦了，我们没有更多的备份服务顶上，所以服务器一旦发生故障，运维人员需要及时处理。</p><p>而 <strong>Bigtable的容灾方式是为主服务指定一个备份服务池</strong>，主服务挂了就从备份服务池中选一个服务作为主服务，如果这个备份服务也挂了，就从池子里再选一个。这种容灾方式，让运维人员可以更从容地处理故障。</p><h2 id="数据模型" tabindex="-1"><strong>数据模型</strong> <a class="header-anchor" href="#数据模型" aria-label="Permalink to &quot;**数据模型**&quot;">​</a></h2><p>了解了Bigtable的可运维性，接着再让我们一起回顾下Bigtable的数据模型。</p><p>Bigtable是一个 <strong>有序的稀疏表</strong>。每一条数据有一个行键，通过行键可以原子性地读写一条数据。一条数据包含了多个列族，不同行数据的同一列族内，可以定义不同的列。每一个列不仅可以保存值，而且可以保存多个版本，每个版本包含了一个时间戳。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/787614b88c0b3ae2fe51be860cbe10aa.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/787614b88c0b3ae2fe51be860cbe10aa.jpg" alt="图片"></a></p><p>Bigtable的数据是按行键的字段顺序排列的，采用动态行键范围分区，分区被称为Tablet。刚开始在Bigtable里，一张表只有一个分区，随着数据越写越多，分区会一分为二，新分区的边界按 <strong>数据密度</strong> 划分，以保证两个分区的数据量大致相同。而如果一个分区的数据删除太多，就会和它相邻的分区合并，新的分区负责原来两个分区行键范围的数据。</p><p>Bigtable的列族是把一组相关的列在物理上放在一起存储，不同的列族会通过逻辑组织在一起。当读写操作只涉及某个列族时，Bigtable只需要处理这个列族对应的物理表即可。 <strong>列族不同于列式存储</strong>，因为列族不是按列分开存储的，而是把多个相关的列打包到一起存储，并且允许每一行有不同的具体列。</p><h2 id="架构与实现" tabindex="-1"><strong>架构与实现</strong> <a class="header-anchor" href="#架构与实现" aria-label="Permalink to &quot;**架构与实现**&quot;">​</a></h2><p>纵观整个Bigtable的系统架构，主要是由4个组件组成的，它们分别是：</p><ul><li>负责提供在线服务的Tablet Server；</li><li>负责存储分区数据Tablet的GFS；</li><li>负责调度Tablet和调整负载的Master；</li><li>负责分布式协调服务的Chubby。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/8dc1681b5723d5f48426f8d6c23a5f7c.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/8dc1681b5723d5f48426f8d6c23a5f7c.jpg" alt="图片"></a></p><p>由于采用动态行键范围分区，Bigtable需要维护行范围到分区的映射关系，以便客户端请求能够路由到正确的Tablet Server上。Bigtable采用了三层树状结构存储数据表的分区信息：</p><ul><li><strong>第一层是Chubby中的一个文件</strong>，它记录了Root Tablet所在的地址。</li><li><strong>第二层是Root Tablet</strong>，它记录了METADATA表的分区信息。METADATA表用于记录所有数据表的分区信息，而它自身也是一张数据表，包含多个分区。Root Tablet特别的地方在于它是METADATA表的第一个分区，并且永远不会分裂。</li><li><strong>第三层是METADATA表的其他分区</strong>，通过这一层就能找到数据所在的实际分区，以及管理这个分区的Tablet Server。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/8969f0ea612e8bb8d98c01bccc586a0e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/8969f0ea612e8bb8d98c01bccc586a0e.jpg" alt="图片"></a></p><p>Bigtable会通过Chubby追踪Tablet Server。当新的Tablet Server添加到集群中的时候，会向Chubby注册自己，Chubby会通知Master有新的Tablet Server加入，Master会把其他Tablet Server管理的Tablet匀一部分，给新加入的Tablet Server。</p><p>Master会通过心跳定时检查Tablet Server的存活状态，如果Tablet Server在Chubby的注册信息不在了，则可以认为Tablet Server处于失效状态，Master会把这个Tablet Server负责的Tablet，分配给其他存活的Tablet Server。</p><p>而因为Bigtable集群只有一个Master服务，如果Master挂了，Chubby就会立即选举一个新的Master。由于读写操作只和Chubby、Tablet Server、Tablet有关，Master只负责调度Tablet和调整负载，所以单Master的架构并不会成为Bigtable的性能瓶颈。</p><h2 id="每秒百万级别的随机读写" tabindex="-1"><strong>每秒百万级别的随机读写</strong> <a class="header-anchor" href="#每秒百万级别的随机读写" aria-label="Permalink to &quot;**每秒百万级别的随机读写**&quot;">​</a></h2><p>Bigtable最耀眼的能力在于 <strong>可以支撑每秒百万级别的随机读写</strong>。它主要是通过两个方法达成这个目标的：</p><ul><li><strong>把随机写变成顺序写；</strong></li><li><strong>尽可能从内存中读。</strong></li></ul><p>我们先来看看Bigtable是如何把随机写变成顺序写的。</p><p>当客户端向Bigtable发起一次随机写请求，会通过三层树状结构的分区信息，找到对应的分区Tablet，以及处理写请求的Tablet Server。Tablet Server将这次写操作记录到Commit Log，然后变更内存表MemTable，当内存表大于某个阈值时，将其作为SSTable文件写入磁盘，并清理Commit Log。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/04d5f97ed69f24ffe3e819107579d401.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/04d5f97ed69f24ffe3e819107579d401.jpg" alt="图片"></a></p><p>接着我们再看看，Bigtable是如何通过内存表MemTable和SSTable文件，完成随机读操作的。</p><p>当客户端向Bigtable发起一次随机读操作，同样会通过三层树状结构的分区信息，找到对应的分区Tablet，以及处理读请求的Tablet Server。Table Server会先从内存表MemTable中查找数据，然后再通过SSTable文件的缓存查找数据，如果都找不到的话，它会再加载SSTable文件，从中查找。</p><p>那么，随着写操作次数的增加，Tablet下的SSTable会越来越多，从而就会影响读操作的性能。因此，Bigtable会把多个SSTable压实成一个SSTable，只保留对一个行键的最后几次操作，这个行为称为 <strong>Major Compaction</strong>。它不仅能够节约硬盘空间，还能够提升读操作性能。</p><p>而除了Major Compaction之外，Bigtable还有一种Compaction，叫做 <strong>Minor Compaction</strong>，它在内存表大于某个阈值时，会将其作为SSTable文件写入磁盘。它的作用是节约内存空间，同时减少内存表恢复时，需要读取的Commit Log大小。</p><p>另外，为了提高随机读的性能，Bigtable其实还做了很多优化。</p><ul><li>首先，它会通过一个 <strong>布隆过滤器</strong>，确定SSTable中是否包含要读取的行键，如果不包含，就快速跳过这个SSTable；</li><li>其次，它会 <strong>缓存查过的数据行和邻近的数据行</strong>，以便下次直接从缓存中读取；</li><li>再次， <strong>SSTable文件中包含了索引数据</strong>，这些索引数据紧凑地放在文件尾部，我们通过索引只需要加载SSTable的部分数据块，就能确定SSTable是否包含要读取的行键，以及行键对应的值；</li><li>最后，由于SSTable是不变的， <strong>访问SSTable不需要加锁</strong>，内存表MemTable采用Copy-On-Write的方式修改，查询内存表也不需要加锁。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/29b209541bef8118820f42376e4644cd.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/440450/29b209541bef8118820f42376e4644cd.jpg" alt="图片"></a></p><h2 id="小结" tabindex="-1"><strong>小结</strong> <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;**小结**&quot;">​</a></h2><p>好了，到这里Bigtable论文的核心内容我们就复习完了。Bigtable主要有两个特点， <strong>第一个是具备良好的可运维性</strong>，服务器支持动态伸缩，数据分区支持动态划分，所有的服务出现故障后，在一定程度内都能自动恢复。 <strong>第二个是能够支撑每秒百万级别的随机读写</strong>，主要的方法有两个，一是把随机写变成顺序写，二是尽可能从内存中读。</p><p>徐老师在 <a href="https://time.geekbang.org/column/article/423602" target="_blank" rel="noreferrer">09</a> 和 <a href="https://time.geekbang.org/column/article/425351" target="_blank" rel="noreferrer">10讲</a> 都推荐了《数据密集型应用系统设计》这本书，如果你还没有开始阅读的话，我强烈建议你读起来。最近一有空我就会拿起这本书翻一翻，对于理解课程内容和拓展数据系统的知识非常有帮助，你也可以参考看看。</p>',44)])])}const h=t(i,[["render",b]]);export{p as __pageData,h as default};
